void dei_ask_handle_frame_programming_mode( void )
{
    UInt8 database_index = dei_ask_check_frame_programming_mode();
                                                    
    if( database_index < DEI_ASK_MAX_REMOTES )
    {
        Cmd_Rf_Pld     btn_pld;
                        
        btn_pld.bits.pld 	  =0; 
        btn_pld.bits.batt_low =0;
        btn_pld.bits.id  	  =database_index;
                        
        cmd_q_rs_insert( INPUT_RF_PROGRAMMING_DONE , 100 , btn_pld.pld);
                        
        dei_ask_database_save();
    }
                    
    dei_ask.last_data_enc = dei_ask.data_enc.data;
    dei_ask.last_data_fix = dei_ask.data_fix.data;
}

